def decrypt1(k, ciphertext):
    c,d,a,b = ciphertext
    c,d,a,b = encrypt2(k, bytes([a,b,c,d]))
    return bytes([a,b,c,d])

def encrypt2(k, plaintext):
    a,b,c,d = plaintext
    for i in range(ROUNDS)[::-1]:
