 def rotl(num, bits):
    bit = num & (1 << (bits-1))
    num <<= 1
    if(bit):
        num |= 1
    num &= (2**bits-1)


     return num


 def rotr(num, bits):
    num &= (2**bits-1)
    bit = num & 1
    num >>= 1
    if(bit):
        num |= (1 << (bits-1))


     return num


 x_org = BitVec("x", 64)
y_org = BitVec("y", 64)
z_org = BitVec("z", 64)


 x, y, z = x_org, y_org, z_org
data_enc = map(ord, open("story4.txt.enc").read()[32:].decode('hex'))
data_dec = map(ord, open("story4.txt").read())


 assert len(data_enc) == len(data_dec)


 s = Solver()
for i in xrange(len(data_dec)):
    s.add( ((data_dec[i] - (x&0xFF)) ^ (y&0xFF) ^ (z&0xFF)) &0xFF == data_enc[i])
    x = RotateRight(x, 1)
    y = RotateLeft(y, 1)
    z = RotateLeft(z, 1)


 if s.check() == sat:
    m = s.model()
    xx = m[x_org].as_long()
    yy = m[y_org].as_long()
    zz = m[z_org].as_long()

    flag_enc = map(ord, open("flag.txt.enc").read()[32:].decode('hex'))
    flag_dec = ""
    for e in flag_enc:
        flag_dec += chr( ((e ^ (yy&0xFF) ^ (zz&0xFF)) + xx&0xFF) & 0xFF )
        xx=rotr(xx, 64)
        yy=rotl(yy, 64)
        zz=rotl(zz, 64)
    print(flag_dec)
